class MainActivity:Activity(){private val bg=Color.rgb(250,246,243);private val wine=Color.rgb(93,16,10);private val ex=Executors.newSingleThreadExecutor();private lateinit var body:LinearLayout;private val pref by lazy{getSharedPreferences("cena",0)};private var restaurant:JSONObject?=null;private var meal:JSONObject?=null;private var slot:JSONObject?=null;private var qty=1;private val mainHandler=Handler(Looper.getMainLooper());private val countdownTasks=mutableListOf<Runnable>();private var feedCursor:String?=null;private var feedLoading=false;private var feedContainer:LinearLayout?=null;private var feedScroll:ScrollView?=null;private val bag=mutableListOf<BagLine>();private var paymentCheckBusy=false;private var paymentRequestInFlight=false;private var lastPaymentPoll=0L;private var paidNotice:String?=null;private var curbsideForCheckout=false;private var curbMake="";private var curbModel="";private var curbColor="";private var bagBadge:TextView?=null;private data class BagLine(val restaurant:JSONObject,val meal:JSONObject,var quantity:Int)
 override fun onCreate(b:Bundle?){super.onCreate(b);window.statusBarColor=bg;window.navigationBarColor=bg;window.decorView.systemUiVisibility=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR;restoreBag();home()}
 override fun onResume(){super.onResume();checkPendingPayment(false)}
