 private fun base(){countdownTasks.forEach{mainHandler.removeCallbacks(it)};countdownTasks.clear();val root=LinearLayout(this).apply{orientation=1;setBackgroundColor(bg)};val sc=ScrollView(this).apply{isVerticalScrollBarEnabled=false;isHorizontalScrollBarEnabled=false};feedScroll=sc;val outer=LinearLayout(this).apply{orientation=1;gravity=Gravity.CENTER_HORIZONTAL;setBackgroundColor(bg)};body=LinearLayout(this).apply{orientation=1;setPadding(22,18,22,24);layoutParams=LinearLayout.LayoutParams(-1,-2).apply{width=resources.displayMetrics.widthPixels.coerceAtMost((600*resources.displayMetrics.density).toInt())}};outer.addView(body);sc.addView(outer);root.addView(sc,LinearLayout.LayoutParams(-1,0,1f));val navOuter=LinearLayout(this).apply{gravity=Gravity.CENTER_HORIZONTAL;setBackgroundColor(Color.WHITE)};val nav=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;layoutParams=LinearLayout.LayoutParams(resources.displayMetrics.widthPixels.coerceAtMost((600*resources.displayMetrics.density).toInt()),(58*resources.displayMetrics.density).toInt());gravity=Gravity.CENTER_VERTICAL};navOuter.addView(nav);root.addView(navOuter);addBottomNavigation(nav);setContentView(root);if(ValueAnimator.areAnimatorsEnabled()){body.alpha=0f;body.translationY=10f;body.animate().alpha(1f).translationY(0f).setDuration(240).start()}}
 private fun addBottomNavigation(nav:LinearLayout){fun tab(label:String,action:()->Unit){nav.addView(Button(this).apply{text=label;textSize=12f;setTextColor(wine);backgroundTintList=android.content.res.ColorStateList.valueOf(Color.WHITE);layoutParams=LinearLayout.LayoutParams(0,-1,1f);setOnClickListener{action()}})};tab("Home"){home()};tab("Orders"){if(pref.getString("token",null)==null)auth()else orders()};val wrap=FrameLayout(this).apply{layoutParams=LinearLayout.LayoutParams(0,-1,1f)};val b=Button(this).apply{text="Bag";textSize=12f;setTextColor(wine);backgroundTintList=android.content.res.ColorStateList.valueOf(Color.WHITE);layoutParams=FrameLayout.LayoutParams(-1,-1);setOnClickListener{bagScreen()}};wrap.addView(b);bagBadge=TextView(this).apply{setTextColor(Color.WHITE);textSize=9f;gravity=Gravity.CENTER;setPadding(5,1,5,1);background=GradientDrawable().apply{setColor(wine);cornerRadius=12*resources.displayMetrics.density};layoutParams=FrameLayout.LayoutParams(-2,(18*resources.displayMetrics.density).toInt(),Gravity.TOP or Gravity.END)};wrap.addView(bagBadge);nav.addView(wrap);updateBagBadge()}
 private fun updateBagBadge(){bagBadge?.apply{text=bag.sumOf{it.quantity}.toString();visibility=if(bag.isEmpty())View.GONE else View.VISIBLE}}
 private fun profileControl(){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.END};row.addView(Button(this).apply{text="Location";textSize=12f;setTextColor(wine);backgroundTintList=android.content.res.ColorStateList.valueOf(bg);setOnClickListener{locationDialog()}});row.addView(Button(this).apply{text=if(pref.getString("token",null)==null)"Sign in" else "Profile";textSize=12f;setTextColor(wine);backgroundTintList=android.content.res.ColorStateList.valueOf(bg);setOnClickListener{if(pref.getString("token",null)==null)auth()else profilePage()}});body.addView(row,0)}
