 private fun title(s:String,z:Float=25f){body.addView(TextView(this).apply{text=s;textSize=z;setTextColor(wine);setPadding(0,9,0,8);typeface=android.graphics.Typeface.DEFAULT_BOLD})};private fun text(s:String){body.addView(TextView(this).apply{text=s;textSize=15f;setTextColor(Color.DKGRAY);setPadding(0,5,0,10)})};private fun button(s:String,f:()->Unit){body.addView(Button(this).apply{text=s;setTextColor(-1);background=GradientDrawable().apply{setColor(wine);cornerRadius=(16f+((390f-resources.displayMetrics.widthPixels/resources.displayMetrics.density)/110f*10f)).coerceIn(16f,26f)*resources.displayMetrics.density};setOnClickListener{f()}})};private fun field(s:String):EditText{val e=EditText(this).apply{hint=s};body.addView(e);return e}
 private fun go(task:()->String,done:(String)->Unit){ex.execute{try{val x=task();runOnUiThread{done(x)}}catch(e:Exception){runOnUiThread{paymentRequestInFlight=false;feedLoading=false;Toast.makeText(this,e.message?:"Request failed",Toast.LENGTH_LONG).show()}}}}
 private fun req(path:String,method:String="GET",data:JSONObject?=null,prefer:String?=null):String{val c=URL(BuildConfig.SUPABASE_URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.connectTimeout=9000;c.readTimeout=12000;c.setRequestProperty("apikey",BuildConfig.SUPABASE_KEY);c.setRequestProperty("Authorization","Bearer "+(pref.getString("token",BuildConfig.SUPABASE_KEY)?:BuildConfig.SUPABASE_KEY));c.setRequestProperty("Content-Type","application/json");if(prefer!=null)c.setRequestProperty("Prefer",prefer);if(data!=null){c.doOutput=true;c.outputStream.use{it.write(data.toString().toByteArray())}};val st=if(c.responseCode<400)c.inputStream else c.errorStream;val out=st.bufferedReader().readText();if(c.responseCode>=400)throw Exception(out);return out}
private fun apiReq(path:String,method:String="GET",data:JSONObject?=null):String{val c=URL(BuildConfig.CENA_API_URL.trimEnd('/')+path).openConnection() as HttpURLConnection;c.requestMethod=method;c.connectTimeout=8000;c.readTimeout=12000;pref.getString("token",null)?.let{c.setRequestProperty("Authorization","Bearer $it")};c.setRequestProperty("Content-Type","application/json");if(data!=null){c.doOutput=true;c.outputStream.use{it.write(data.toString().toByteArray())}};val code=c.responseCode;val stream=if(code<400)c.inputStream else c.errorStream;val out=stream.bufferedReader().readText();if(code>=400)throw Exception(out);return out}
 private fun restoreBag(){bag.clear();try{val saved=JSONArray(pref.getString("bag_json","[]"));for(i in 0 until saved.length()){val entry=saved.getJSONObject(i);bag.add(BagLine(entry.getJSONObject("restaurant"),entry.getJSONObject("meal"),entry.optInt("quantity",1).coerceAtLeast(1)))}}catch(_:Exception){bag.clear()}}
 private fun persistBag(){val a=JSONArray();for(line in bag)a.put(JSONObject().put("restaurant",line.restaurant).put("meal",line.meal).put("quantity",line.quantity));pref.edit().putString("bag_json",a.toString()).apply()}
 private fun validCheckoutUrl(value:String):Boolean{try{val uri=java.net.URI(value);return uri.scheme=="https"&&uri.host.equals("checkout.stripe.com",true)&&uri.userInfo==null}catch(_:Exception){return false}}
 private fun clearPaymentMarkers(){pref.edit().remove("pending_checkout_order").remove("pending_checkout_url").remove("pending_checkout_user_id").remove("checkout_request").remove("checkout_idempotency_key").remove("checkout_user_id").commit()}
 private fun finishPaidPayment(){bag.clear();persistBag();clearPaymentMarkers();paidNotice="Payment confirmed. Your order is in My orders.";updateBagBadge();home()}
 private fun paymentOwnerMatches():Boolean{val owner=pref.getString("pending_checkout_user_id",null)?:pref.getString("checkout_user_id",null);val user=pref.getString("user_id",null);return !pref.getString("token",null).isNullOrBlank()&&owner!=null&&owner==user}
 private fun openPendingCheckout(){if(!paymentOwnerMatches()){Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};val url=pref.getString("pending_checkout_url",null)?:return;if(!validCheckoutUrl(url)){Toast.makeText(this,"Checkout address could not be verified. Your bag is safe.",Toast.LENGTH_LONG).show();return};try{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(url)))}catch(_:Exception){Toast.makeText(this,"Could not open secure checkout. Your bag is saved.",Toast.LENGTH_LONG).show()}}
 private fun checkPendingPayment(showPending:Boolean,resumeCheckout:Boolean=false){val id=pref.getString("pending_checkout_order",null)?:return;if(!paymentOwnerMatches()){if(showPending)Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};if(paymentCheckBusy||(System.currentTimeMillis()-lastPaymentPoll<1500&&!resumeCheckout))return;paymentCheckBusy=true;lastPaymentPoll=System.currentTimeMillis();ex.execute{try{val status=JSONObject(apiReq("/v1/checkout/$id")).optString("status");runOnUiThread{paymentCheckBusy=false;when(status){"paid"->finishPaidPayment();"expired","failed"->{clearPaymentMarkers();if(showPending)Toast.makeText(this,"Checkout $status. Your bag is safe; continue to pickup to try again.",Toast.LENGTH_LONG).show()};"refunded"->{clearPaymentMarkers();if(showPending)Toast.makeText(this,"This checkout was refunded. Your bag is safe.",Toast.LENGTH_LONG).show()};"pending"->{if(resumeCheckout)openPendingCheckout()else if(showPending)Toast.makeText(this,"Payment is still processing. Your bag is safe.",Toast.LENGTH_LONG).show()};else->{if(showPending)Toast.makeText(this,"Payment status is still being confirmed.",Toast.LENGTH_LONG).show()}}}}catch(e:Exception){runOnUiThread{paymentCheckBusy=false;if(showPending)Toast.makeText(this,e.message?:"Could not check payment yet.",Toast.LENGTH_LONG).show()}}}}
 private fun cancelPendingCheckout(){val id=pref.getString("pending_checkout_order",null)?:return;if(!paymentOwnerMatches()){Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};go({apiReq("/v1/checkout/$id","DELETE")}){val status=JSONObject(it).optString("status");when(status){"expired"->{clearPaymentMarkers();Toast.makeText(this,"Checkout canceled. Your bag is still here.",Toast.LENGTH_LONG).show();bagScreen()};"refunded"->{clearPaymentMarkers();Toast.makeText(this,"This checkout was refunded. Your bag is safe.",Toast.LENGTH_LONG).show();bagScreen()};"paid"->finishPaidPayment();else->Toast.makeText(this,"Checkout is still being confirmed. Your bag is safe.",Toast.LENGTH_LONG).show()}}}
 private fun submitCheckoutRequest(request:JSONObject){if(paymentRequestInFlight)return;paymentRequestInFlight=true;val owner=pref.getString("checkout_user_id",null);val user=pref.getString("user_id",null);if(owner==null||owner!=user){paymentRequestInFlight=false;Toast.makeText(this,"Sign in with the account that started this checkout.",Toast.LENGTH_LONG).show();return};go({try{val response=JSONObject(apiReq("/v1/checkout","POST",request));response.put("_checkout_owner",owner);response.toString()}catch(e:Exception){val status=try{JSONObject(e.message?:"").optString("status")}catch(_:Exception){""};if(status=="expired"||status=="failed"||status=="refunded"){clearPaymentMarkers();val message=if(status=="refunded")"The previous checkout was refunded. Your bag is safe; no new charge was made." else "The previous checkout $status. Your bag is safe; tap Pay securely in Cena to start again.";throw Exception(message)};throw e}}){response->paymentRequestInFlight=false;val payment=JSONObject(response);val id=payment.getString("order_id");val url=payment.optString("checkout_url");val editor=pref.edit().putString("pending_checkout_order",id).putString("pending_checkout_user_id",payment.optString("_checkout_owner"));if(validCheckoutUrl(url))editor.putString("pending_checkout_url",url);editor.commit();if(payment.optString("status")=="paid")checkPendingPayment(true)else if(validCheckoutUrl(url))openPendingCheckout()else Toast.makeText(this,"Your order is saved, but the secure checkout address could not be verified. Your bag is safe.",Toast.LENGTH_LONG).show()}}
 private fun startCheckout(){if(paymentRequestInFlight)return;if(bag.isEmpty()||slot==null){Toast.makeText(this,"Add meal kits and choose a pickup time first.",Toast.LENGTH_SHORT).show();return};if(pref.getString("token",null)==null){auth();return};val pending=pref.getString("pending_checkout_order",null);if(pending!=null){checkPendingPayment(true,true);return};if(pref.getString("checkout_request",null)!=null){val saved=pref.getString("checkout_request",null)?:return;submitCheckoutRequest(JSONObject(saved));return};paymentRequestInFlight=true;persistBag();go({val user=JSONObject(req("/auth/v1/user"));val owner=user.getString("id");val items=JSONArray();for(line in bag)items.put(JSONObject().put("item_id",line.meal.getString("id")).put("quantity",line.quantity));val key=java.util.UUID.randomUUID().toString();val vehicle=if(curbsideForCheckout)JSONObject().put("make",curbMake).put("model",curbModel).put("color",curbColor)else JSONObject();val request=JSONObject().put("p_restaurant_id",bag.first().restaurant.getString("id")).put("p_slot_id",slot!!.getString("id")).put("p_idempotency_key",key).put("p_pickup_mode",if(curbsideForCheckout)"curbside" else "counter").put("p_vehicle",vehicle).put("p_items",items);pref.edit().putString("user_id",owner).putString("checkout_user_id",owner).putString("checkout_idempotency_key",key).putString("checkout_request",request.toString()).commit();request.toString()}){request->paymentRequestInFlight=false;submitCheckoutRequest(JSONObject(request))}}
 private fun imageResource(key:String):Int { val safe=key.lowercase().replace("-","_");val found=resources.getIdentifier(safe,"drawable",packageName);if(found!=0)return found;return when(safe){"sunrise_cafe_cover"->R.drawable.tacos;"little_fig_cover"->R.drawable.mediterranean;else->R.drawable.mediterranean} }
private fun profilePage(){base();profileControl();title("Your Cena profile");if(pref.getString("token",null)==null){text("Sign in to save your name, phone and kitchen equipment across devices.");button("Sign in with email code"){auth()};return};text("Signed in as ${pref.getString("email","your Cena account")}");val name=field("Display name");name.maxLines=1;val phone=field("Phone number");phone.inputType=3;text("Kitchen equipment");val equipment=linkedMapOf<String,CheckBox>();for(option in listOf("Oven","Stovetop","Toaster","Panini press")){val check=CheckBox(this).apply{text=option;setTextColor(wine)};equipment[option]=check;body.addView(check)};val status=TextView(this).apply{textSize=13f;setTextColor(Color.rgb(28,112,61));setPadding(0,8,0,8)};body.addView(status);val save=Button(this).apply{text="Save profile";isEnabled=false;setOnClickListener{go({val user=JSONObject(req("/auth/v1/user"));val selected=JSONArray();equipment.filterValues{it.isChecked}.keys.forEach{selected.put(it)};val payload=JSONObject().put("id",user.getString("id")).put("display_name",name.text.toString().trim().take(80)).put("phone",if(phone.text.toString().isBlank())JSONObject.NULL else phone.text.toString().trim()).put("equipment",selected);req("/rest/v1/profiles?on_conflict=id","POST",payload,"resolution=merge-duplicates,return=minimal")}){status.text="Profile saved to your Cena account."}}};body.addView(save);button("Sign out"){if((pref.getString("pending_checkout_order",null)!=null||pref.getString("checkout_request",null)!=null)&&paymentOwnerMatches())Toast.makeText(this,"Complete or cancel the pending checkout before signing out.",Toast.LENGTH_LONG).show()else{pref.edit().remove("token").remove("email").remove("refresh").remove("user_id").apply();home()}};go({val user=JSONObject(req("/auth/v1/user"));val id=user.getString("id");val rows=JSONArray(req("/rest/v1/profiles?select=display_name,phone,equipment&id=eq.$id&limit=1"));rows.optJSONObject(0)?.toString()?:"{}"}){val profile=JSONObject(it);name.setText(profile.optString("display_name"));phone.setText(profile.optString("phone"));val saved=profile.optJSONArray("equipment")?:JSONArray();for((option,check) in equipment)check.isChecked=(0 until saved.length()).any{saved.optString(it)==option};save.isEnabled=true}}
 private fun addToBag(r:JSONObject,m:JSONObject){if(paymentRequestInFlight||pref.getString("pending_checkout_order",null)!=null||pref.getString("checkout_request",null)!=null){Toast.makeText(this,"Finish or cancel the current checkout before changing your bag.",Toast.LENGTH_LONG).show();return};val rid=r.optString("id");val current=bag.firstOrNull()?.restaurant?.optString("id");if(current!=null&&current!=rid){AlertDialog.Builder(this).setTitle("One restaurant per order").setMessage("Your bag has items from ${bag.first().restaurant.optString("name")}. Replace it with items from ${r.optString("name")}?").setNegativeButton("Keep current bag",null).setPositiveButton("Replace bag"){_,_->bag.clear();bag.add(BagLine(r,m,1));persistBag();updateBagBadge();Toast.makeText(this,"Added to bag",Toast.LENGTH_SHORT).show()}.show();return};val existing=bag.firstOrNull{it.meal.optString("id")==m.optString("id")};if(existing!=null)existing.quantity++ else bag.add(BagLine(r,m,1));persistBag();updateBagBadge();Toast.makeText(this,"Added to bag",Toast.LENGTH_SHORT).show()}
 private fun bagScreen(){base();title("Your bag");if(bag.isEmpty()){text("Your bag is empty.");button("Explore meal kits"){catalog()};return};val pending=pref.getString("pending_checkout_order",null);val request=pref.getString("checkout_request",null);if(paymentRequestInFlight){text("Your secure checkout is being prepared. The bag is locked.");return};if(pending!=null||request!=null){if(!paymentOwnerMatches()){text("This checkout belongs to another Cena account. Sign in with the account that started it.");button("Switch account"){pref.edit().remove("token").remove("email").remove("refresh").remove("user_id").apply();auth()};return};if(pending==null){text("Your checkout request is saved. Your bag is locked while payment is confirmed.");button("Retry secure checkout"){startCheckout()};return};text("Payment for order $pending is still being confirmed. Your bag is saved.");button("Continue secure checkout"){checkPendingPayment(true,true)};button("Check payment status"){checkPendingPayment(true)};button("Cancel checkout"){cancelPendingCheckout()};return};text("${bag.first().restaurant.optString("name")} · pickup orders are placed one restaurant at a time");for(line in bag.toList()){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(0,8,0,8)};row.addView(TextView(this).apply{text="${line.meal.optString("name")}\nMeal kit · $${"%.2f".format(line.meal.optInt("price_cents")/100.0)} each";textSize=14f;setTextColor(wine);layoutParams=LinearLayout.LayoutParams(0,-2,1f)});row.addView(Button(this).apply{text="−";contentDescription="Remove one ${line.meal.optString("name")}";setOnClickListener{if(line.quantity<=1)bag.remove(line)else line.quantity--;persistBag();updateBagBadge();bagScreen()}});row.addView(TextView(this).apply{text=line.quantity.toString();textSize=15f;setTextColor(wine);setPadding(8,0,8,0)});row.addView(Button(this).apply{text="+";contentDescription="Add one ${line.meal.optString("name")}";setOnClickListener{line.quantity++;persistBag();updateBagBadge();bagScreen()}});row.addView(Button(this).apply{text="Remove";contentDescription="Remove ${line.meal.optString("name")} from bag";setOnClickListener{bag.remove(line);persistBag();updateBagBadge();bagScreen()}});body.addView(row)};val subtotal=bag.sumOf{it.meal.optInt("price_cents",0)*it.quantity};title("Kit subtotal · $${"%.2f".format(subtotal/100.0)}",18f);button("Continue to pickup"){restaurant=bag.first().restaurant;meal=bag.first().meal;qty=bag.first().quantity;loadSlots()};button("Browse this restaurant"){restaurant=bag.first().restaurant;menu()}}
 private fun home(){base();brandHeader();text("Good food, slower hours. Reserve local meal kits for pickup.");paidNotice?.let{title(it,16f);paidNotice=null};body.addView(TextView(this).apply{text="⌖  FROM SAN FRANCISCO\nPickup-area center · distances are approximate";textSize=19f;setTextColor(wine);setPadding(18,28,18,28);setBackgroundColor(Color.rgb(239,228,218));setOnClickListener{startActivity(Intent(Intent.ACTION_VIEW,Uri.parse("geo:37.7749,-122.4194?q=meal+kit+pickup")))}});text("Discover neighborhood kitchens and their next available pickup times.");button("Browse pickup options"){catalog()};text("Same-day or scheduled pickup · Pay securely in Cena")}
 private fun auth(){base();title("Your Cena account");text("We'll email you a one-time sign-in code.");val e=field("Email address");val c=field("6-digit code");button("Send code"){go({req("/auth/v1/otp","POST",JSONObject().put("email",e.text.toString().trim()).put("create_user",true))}){Toast.makeText(this,"Check your email",Toast.LENGTH_LONG).show()}};button("Verify code"){go({req("/auth/v1/verify","POST",JSONObject().put("email",e.text.toString().trim()).put("token",c.text.toString().trim()).put("type","email"))}){val j=JSONObject(it);pref.edit().putString("token",j.optString("access_token")).putString("refresh",j.optString("refresh_token")).putString("email",e.text.toString().trim()).putString("user_id",j.optJSONObject("user")?.optString("id")?:"").apply();catalog()}};button("Back"){home()}}
private val sfLat=37.7749
 private val sfLon=-122.4194
 private var originLat=sfLat;private var originLon=sfLon;private var usingDeviceLocation=false;private var manualLocation:String?=null
private fun locationDialog(){val input=EditText(this).apply{hint="Street address, city, state";setSingleLine();setText(manualLocation?:"")};lateinit var dialog:AlertDialog;val content=LinearLayout(this).apply{orientation=1;setPadding(24,8,24,0);addView(input);addView(Button(this@MainActivity).apply{text="Use approximate device location";setOnClickListener{dialog.dismiss();requestApproxLocation()}});addView(Button(this@MainActivity).apply{text="Use San Francisco pickup area";setOnClickListener{dialog.dismiss();usingDeviceLocation=false;manualLocation=null;originLat=sfLat;originLon=sfLon;catalog()}})};dialog=AlertDialog.Builder(this).setTitle("Pickup location").setView(content).setPositiveButton("Find address",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener{val address=input.text.toString().trim();if(address.isNotBlank()){dialog.dismiss();resolveAddress(address)}else input.error="Enter an address"}};dialog.show()}
 private fun resolveAddress(address:String){go({val encoded=java.net.URLEncoder.encode(address,"UTF-8");val c=URL(BuildConfig.CENA_API_URL.trimEnd('/')+"/v1/geocode?address="+encoded).openConnection() as HttpURLConnection;c.requestMethod="GET";c.connectTimeout=5000;c.readTimeout=5000;c.setRequestProperty("Accept","application/json");val code=c.responseCode;val stream=if(code<400)c.inputStream else c.errorStream;val result=stream.bufferedReader().readText();if(code>=400)throw Exception(result);result}){val result=JSONObject(it);originLat=kotlin.math.round(result.getDouble("latitude")*100.0)/100.0;originLon=kotlin.math.round(result.getDouble("longitude")*100.0)/100.0;manualLocation=result.optString("label",address);usingDeviceLocation=false;catalog()}}
 private fun requestApproxLocation(){if(checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(arrayOf(Manifest.permission.ACCESS_COARSE_LOCATION),503);return};try{val lm=getSystemService(LOCATION_SERVICE) as LocationManager;val loc=listOf(LocationManager.NETWORK_PROVIDER,LocationManager.GPS_PROVIDER).mapNotNull{provider->try{lm.getLastKnownLocation(provider)}catch(_:Exception){null}}.maxByOrNull{it.time};if(loc==null||System.currentTimeMillis()-loc.time>900000L){Toast.makeText(this,"No recent location fix. Your pickup location was not changed.",Toast.LENGTH_LONG).show();return};originLat=kotlin.math.round(loc.latitude*100.0)/100.0;originLon=kotlin.math.round(loc.longitude*100.0)/100.0;usingDeviceLocation=true;manualLocation=null;catalog()}catch(_:Exception){Toast.makeText(this,"Location unavailable. Your pickup location was not changed.",Toast.LENGTH_LONG).show()}}
 override fun onRequestPermissionsResult(requestCode:Int,permissions:Array<out String>,grantResults:IntArray){super.onRequestPermissionsResult(requestCode,permissions,grantResults);if(requestCode==503&&grantResults.firstOrNull()==PackageManager.PERMISSION_GRANTED)requestApproxLocation()}
 private fun catalog(){if(BuildConfig.SUPABASE_URL.isBlank()){base();title("Kitchens nearby");text("Set your Supabase URL and public key in Gradle user properties to load live pickup options.");button("Back"){home()};return};feedCursor=null;loadFeed(null)}
 private fun loadFeed(after:String?){if(feedLoading)return;feedLoading=true;go({val ids=JSONArray();val recentMeals=JSONArray();if(after==null&&pref.getString("token",null)!=null){try{val history=JSONArray(req("/rest/v1/orders?select=restaurant_id,restaurant:restaurants(id,slug,name,cuisine,address,image_key,curbside_enabled),items:order_items(item_id,name_snapshot,quantity,unit_price_cents)&order=created_at.desc&limit=8"));val seen=hashSetOf<String>();for(i in 0 until history.length()){val order=history.getJSONObject(i);val id=order.optString("restaurant_id");if(id.isNotBlank()&&seen.add(id))ids.put(id);val r=order.optJSONObject("restaurant")?:continue;val lines=order.optJSONArray("items")?:continue;for(j in 0 until lines.length()){val line=lines.getJSONObject(j);val m=JSONObject().put("id",line.optString("item_id")).put("name",line.optString("name_snapshot")).put("recent_quantity",line.optInt("quantity"));recentMeals.put(JSONObject().put("restaurant",r).put("meal",m));if(recentMeals.length()>=12)break};if(recentMeals.length()>=12)break}}catch(_:Exception){}};val p=JSONObject().put("p_latitude",originLat).put("p_longitude",originLon).put("p_after",after?:JSONObject.NULL).put("p_query",JSONObject.NULL).put("p_cuisine",JSONObject.NULL).put("p_recent_ids",ids);val response=JSONObject(req("/rest/v1/rpc/discover_pickup_feed","POST",p));response.put("recent_meals",recentMeals);response.toString()}){feedLoading=false;val result=JSONObject(it);feedCursor=if(result.isNull("next_cursor"))null else result.optString("next_cursor");renderFeed(result,after==null)}}
 private fun renderFeed(data:JSONObject,first:Boolean){if(first){base();profileControl();title(if(usingDeviceLocation)"Pickup near you" else if(manualLocation!=null)"Pickup near $manualLocation" else "Pickup around San Francisco");text(if(usingDeviceLocation)"Approximate location · distances rounded to the nearest 0.01°" else if(manualLocation!=null)"From $manualLocation" else "From San Francisco · local pickup-area center");feedContainer=body;val recent=data.optJSONArray("recent")?:JSONArray();section("Recents");addRestaurantRail(recent,"No recent pickups yet. Your reservations will appear here.");section("Recent meal kits");addMealRail(data.optJSONArray("recent_meals")?:JSONArray());section("Near you");addRestaurantRail(data.optJSONArray("nearby")?:JSONArray(),"No pickup kitchens found in this area yet.");section("Explore by cuisine");addCuisinePage(data.optJSONArray("categories")?:JSONArray());feedScroll?.setOnScrollChangeListener{v:View,_,y,_,_->val sc=v as ScrollView;if(!feedLoading&&feedCursor!=null&&y+sc.height>=sc.getChildAt(0).height-(180*resources.displayMetrics.density).toInt())loadFeed(feedCursor)};pageIfNeeded()}else{addCuisinePage(data.optJSONArray("categories")?:JSONArray());pageIfNeeded()}}
 private fun pageIfNeeded(){feedScroll?.post{val sc=feedScroll;val child=sc?.getChildAt(0);if(sc!=null&&child!=null&&feedCursor!=null&&!feedLoading&&child.height<sc.height+(180*resources.displayMetrics.density).toInt())loadFeed(feedCursor)}}
 private fun section(name:String){title(name,20f)}
 private fun addRestaurantRail(restaurants:JSONArray,emptyMessage:String=""){if(restaurants.length()==0){if(emptyMessage.isNotBlank())text(emptyMessage);return};val rail=HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false;isVerticalScrollBarEnabled=false};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};rail.addView(row);feedContainer?.addView(rail);for(i in 0 until restaurants.length()){val r=restaurants.optJSONObject(i)?:continue;val card=LinearLayout(this).apply{orientation=1;setPadding(0,0,14,10);layoutParams=LinearLayout.LayoutParams((250*resources.displayMetrics.density).toInt(),-2)};val photo=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(142*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(r.optString("image_key","mediterranean")))};card.addView(photo);val miles=r.optDouble("distance_miles",Double.NaN);val dist=if(miles.isNaN())"Distance unavailable" else if(usingDeviceLocation)"%.1f mi away".format(miles) else if(manualLocation!=null)"%.1f mi from $manualLocation".format(miles) else "%.1f mi from San Francisco".format(miles);val next=r.optJSONObject("next_slot")?.optString("starts_at")?.replace("T"," · ")?.take(16)?:"Check pickup times";card.addView(TextView(this).apply{text="${r.optString("name")} · ${r.optString("cuisine")}\n$dist\n$next";textSize=15f;setTextColor(wine);setPadding(8,8,8,6);typeface=android.graphics.Typeface.DEFAULT_BOLD});card.setOnClickListener{restaurant=r;menu()};row.addView(card)}}
 private fun preparedPriceView(item:JSONObject):TextView? {val kit=item.optInt("price_cents",0);val prepared=item.optInt("prepared_meal_total_cents",0);if(prepared<=kit||prepared<=0)return null;val label="Prepared meal including tax · $${"%.2f".format(prepared/100.0)}";return TextView(this).apply{text=label;contentDescription=label;textSize=11f;setTextColor(Color.DKGRAY);setPadding(7,3,7,8);paintFlags=paintFlags or Paint.STRIKE_THRU_TEXT_FLAG;importantForAccessibility=View.IMPORTANT_FOR_ACCESSIBILITY_YES}}
 private fun addMealRail(meals:JSONArray){if(meals.length()==0){text("Previously ordered meal kits will appear here.");return};val rail=HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false;isVerticalScrollBarEnabled=false};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};rail.addView(row);feedContainer?.addView(rail);for(i in 0 until meals.length()){val entry=meals.optJSONObject(i)?:continue;val m=entry.optJSONObject("meal")?:continue;val r=entry.optJSONObject("restaurant")?:continue;val card=LinearLayout(this).apply{orientation=1;layoutParams=LinearLayout.LayoutParams((240*resources.displayMetrics.density).toInt(),-2).apply{rightMargin=(12*resources.displayMetrics.density).toInt()}};card.addView(ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(140*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(m.optString("image_key","mediterranean")))});card.addView(TextView(this).apply{text="${m.optString("name")}\n${r.optString("name")}\nPreviously ordered · ${m.optInt("recent_quantity")} last time";textSize=14f;setTextColor(wine);setPadding(7,8,7,7);typeface=android.graphics.Typeface.DEFAULT_BOLD});preparedPriceView(m)?.let{card.addView(it)};card.setOnClickListener{restaurant=r;menu()};row.addView(card)}}
 private fun addCuisinePage(categories:JSONArray){for(i in 0 until categories.length()){val cat=categories.optJSONObject(i)?:continue;val restaurants=cat.optJSONArray("restaurants")?:JSONArray();if(restaurants.length()==0)continue;section(cat.optString("name","More nearby"));addRestaurantRail(restaurants)}} private fun menu(){val r=restaurant!!;go({req("/rest/v1/catalog_items?select=id,name,description,price_cents,prepared_meal_total_cents,image_key&restaurant_id=eq.${r.getString("id")}&active=eq.true&published_at=not.is.null&order=name")}){val a=JSONArray(it);base();profileControl();title(r.optString("name"));text(r.optString("address"));for(i in 0 until a.length()){val m=a.getJSONObject(i);val photo=ImageView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,(190*resources.displayMetrics.density).toInt());scaleType=ImageView.ScaleType.CENTER_CROP;setImageResource(imageResource(m.optString("image_key","mediterranean")))};body.addView(photo);button("${m.optString("name")}\n${m.optString("description")}\nMeal kit · $${"%.2f".format(m.optInt("price_cents")/100.0)}"){addToBag(r,m)};preparedPriceView(m)?.let{body.addView(it)}};button("Back to kitchens"){catalog()}}}
 private fun loadSlots(){val r=restaurant!!;go({req("/rest/v1/pickup_slots?select=id,starts_at,ends_at,cutoff_at&restaurant_id=eq.${r.getString("id")}&active=eq.true&starts_at=gt.${java.time.Instant.now().plusSeconds(32*60)}&cutoff_at=gt.${java.time.Instant.now()}&order=starts_at")}){val a=JSONArray(it);base();title("Choose pickup day");text("Payment requires a pickup window at least 32 minutes away.");if(a.length()==0)text("No eligible pickup windows remain. Choose another day or check again later.");val days=(0 until a.length()).map{a.getJSONObject(it).optString("starts_at").take(10)}.distinct();for(day in days)button(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth}){showTimes(day,a)};button("Back to menu"){menu()}}}
private fun showTimes(day:String,a:JSONArray){base();title(java.time.LocalDate.parse(day).let{it.dayOfWeek.name.lowercase().replaceFirstChar(Char::uppercase)+", "+it.month.name.lowercase().replaceFirstChar(Char::uppercase)+" "+it.dayOfMonth});for(i in 0 until a.length()){val sl=a.getJSONObject(i);if(!sl.optString("starts_at").startsWith(day))continue;val cutoff=java.time.Instant.parse(sl.optString("cutoff_at")).toEpochMilli();val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(12,10,12,10);background=GradientDrawable().apply{setColor(Color.WHITE);cornerRadius=14*resources.displayMetrics.density};layoutParams=LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=(10*resources.displayMetrics.density).toInt()}};row.addView(TextView(this).apply{text=sl.optString("starts_at").substring(11,16);textSize=19f;setTextColor(wine);typeface=android.graphics.Typeface.DEFAULT_BOLD;layoutParams=LinearLayout.LayoutParams(0,-2,1f)});val badge=TextView(this).apply{setTextColor(Color.rgb(28,112,61));textSize=13f;setPadding(10,7,10,7);background=GradientDrawable().apply{setColor(Color.rgb(239,249,240));cornerRadius=12*resources.displayMetrics.density;setStroke((1*resources.displayMetrics.density).toInt(),Color.rgb(53,142,83))}};row.addView(badge);val tick=object:Runnable{override fun run(){val left=(cutoff-System.currentTimeMillis()).coerceAtLeast(0);val sec=left/1000;badge.text="Order cutoff for pickup today · %02d:%02d:%02d".format(sec/3600,(sec%3600)/60,sec%60);row.isEnabled=left>0;badge.alpha=if(left>0)1f else .55f;if(left>0)mainHandler.postDelayed(this,1000)}};countdownTasks.add(tick);tick.run();row.setOnClickListener{slot=sl;checkout()};body.addView(row)};button("Choose another day"){loadSlots()}}private fun checkout(){if(bag.isEmpty()){bagScreen();return};restaurant=bag.first().restaurant;base();profileControl();title("Pickup details");text(restaurant?.optString("name")?:"");for(line in bag)text("${line.quantity} × ${line.meal.optString("name")} · $${"%.2f".format(line.meal.optInt("price_cents")*line.quantity/100.0)}");val subtotal=bag.sumOf{it.meal.optInt("price_cents",0)*it.quantity};title("Kit subtotal · $${"%.2f".format(subtotal/100.0)}",18f);text("Pickup ${slot?.optString("starts_at")?.replace("T"," · ")?.take(16)?:"time selected"}");val curb=CheckBox(this).apply{text="Curbside pickup";isChecked=curbsideForCheckout;setTextColor(wine)};body.addView(curb);val brand=field("Vehicle make");brand.setText(curbMake);val model=field("Vehicle model");model.setText(curbModel);val color=field("Vehicle color");color.setText(curbColor);listOf(brand,model,color).forEach{it.visibility=if(curb.isChecked)View.VISIBLE else View.GONE};curb.setOnCheckedChangeListener{_,checked->curbsideForCheckout=checked;listOf(brand,model,color).forEach{it.visibility=if(checked)View.VISIBLE else View.GONE}};button("Pay securely in Cena"){curbsideForCheckout=curb.isChecked;curbMake=brand.text.toString();curbModel=model.text.toString();curbColor=color.text.toString();startCheckout()};button("Back to pickup times"){loadSlots()}}
 private fun orders(){go({req("/rest/v1/orders?select=id,status,subtotal_cents,pickup_starts_at,restaurants(name)&order=created_at.desc&limit=20")}){val a=JSONArray(it);base();title("My reservations");if(a.length()==0)text("No reservations yet.");for(i in 0 until a.length()){val o=a.getJSONObject(i);text("${o.optJSONObject("restaurants")?.optString("name")} · ${o.optString("status")}\n${o.optString("pickup_starts_at").replace("T"," · ").take(17)}")};button("Back"){home()}}}
}
